import {parseGameJson} from './game-json.js';
import {componentDefaultValues,defaultsForObject,editComponentProperty,validComponentProperties} from './scene-components.js';
import {deformableParticleCount} from './deformable-distribution.js';
const sparse=new Set(['massWeights','pinWeights','pinOverrides','motionLimits','distanceTethers']);
export function componentSparseParticleCount(type,key,p){if(!['Cloth','Rope2D'].includes(type)||!sparse.has(key))return 0;const count=deformableParticleCount(p);return Number.isSafeInteger(count)&&count>=2&&count<=(type==='Rope2D'?4096:65536)?count:0;}
export function componentJsonTextLimit(type,key,p){return Math.max(262144,componentSparseParticleCount(type,key,p)*128);}
export function parseComponentJson(text,type,key,p){if(!componentSparseParticleCount(type,key,p))return parseGameJson(text,{object:false});if(typeof text!=='string'||text.length>componentJsonTextLimit(type,key,p))throw Error('입자 속성 JSON 전송 크기를 확인하세요.');const value=JSON.parse(text);if(!Array.isArray(value)||!validComponentProperties(type,{...p,[key]:value}))throw Error('입자 속성의 배열·번호·가중치·중복을 확인하세요.');return value;}
export class ComponentJsonOperationState{
 constructor(objects){this.objects=objects;this.overrides=new Map();}
 resolve(operation){const a=operation.args,object=this.objects.get(a.target===null||a.target==='self'||a.target===undefined?operation.self:a.target),component=(object?.components||object&&defaultsForObject(object.kind)||[]).find(c=>[c.id,c.name,c.type].includes(a.component));if(!component||!['Cloth','Rope2D'].includes(component.type))return null;return{component,properties:this.overrides.get(component)||{...componentDefaultValues(component.type),...component.properties}};}
 json(operation){const row=this.resolve(operation);if(!row||!componentSparseParticleCount(row.component.type,operation.args.property,row.properties))return false;const value=parseComponentJson(operation.args.json,row.component.type,operation.args.property,row.properties);this.overrides.set(row.component,{...row.properties,[operation.args.property]:value});return true;}
 observe(operation){if(!['componentSetFloat','componentSetString'].includes(operation.key)||!['columns','rows','particles','topology'].includes(operation.args.property))return;const row=this.resolve(operation);if(!row)return;const next=editComponentProperty(row.component.type,row.properties,operation.args.property,operation.args.value);if(!validComponentProperties(row.component.type,next))throw Error('입자 토폴로지 작업 범위를 확인하세요.');this.overrides.set(row.component,next);}
}
export const componentJsonContract=Object.freeze({generic:'Existing game JSON depth32/nodes10000/array4096/text262144 limits unchanged for every ordinary property',sparse:{components:['Cloth','Rope2D'],fields:[...sparse],limit:'max(262144, authored particle count *128) text bytes for valid ASCII schema payloads; count uses existing grid/rope topology, at most65536 physical particles',validation:'Only complete typed sparse arrays; existing component validator enforces row fields, indices, unique indices/pairs, positive masses, unit pin weights and ranges. No arbitrary nested/object/struct JSON bypass.'},cpp:'Existing Components::SetText uses the same topology-derived budget and sparse shape validation before enqueue/local snapshot mutation; generic API signature unchanged',scope:'Command payload support for full authored grids; no increase in physics capacity, body allocation, GPU or FPS guarantee.'});
